INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p977274-pe002', 'stk-faisal_2011', 'PE 002', 'info', '{"desc": "رحت للدكتور ، حسن المسلم ، قلت له بسجل في weight control\nاخذ مني البيانات : ( اسم الطالب - الرقم الجامعي - الكورس\" PE002 \" - السكشن - اسم الدكتور حقك \"\n\nقال لي ، تعال الاسبوع الثالث بالدراسة ! لمبنى ١١ ، الساعة ٥:٣٠ المغرب ، الاحد و الثلاثاء\n---\nيعني تحظر مع دكتورك اول ٤ كلاسات بس ! وبعدها تروح للويت كنترول ، و ترجع لدكتورك القديم اخر اسبوعين بالسميستر عشان الاختبار حق الهيلث", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/119329/12", "user": "Faisal_2011", "ts": 1328002739000, "tid": 119329, "pn": 12}}', 1328002739000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1350440-pe002', 'stk-aabbcc1212', 'PE 002', 'info', '{"desc": "انا نفس وضعك دخلت بداية الترم وانا ما اعرف اسبح ولمدة اربع اسابيع وطبعا انتهت الاربع الاسابيع وانا ع نفس وضعي ويوم جاء الاختبار قلت للمدرس ما اعرف انا ومعي مجموعة الزبدة قال راح اعطيكم c في السباحة . الزبدة من كلامي حتى لو اخذت صفر مستحيل ترسب خصوصا وان الكورس غير مختصر ع السباحة فيمديك تعوض فالتنس وعدم الغياب …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe-002/159616/2", "user": "Aabbcc1212", "ts": 1397080198000, "tid": 159616, "pn": 2}}', 1397080198000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ambitiouss-pe002', 'stk-ambitiouss', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 Term 132\nوالله يا شباب احسكم تتكلمون عن شخص ثاني, الأستاذ حمدان قمة في الأخلاق والتعامل وجدا متفاهم إلا في الحضور (يسمح بغياب واحد فقط) غير كذا خصم لكل غياب بدون عذر. أخذت بونس الماراثون 5 درجات وخذت A+ مع اني غير رياضي ولا شبكته ولا يعرف اسمي. لكني مجتهد معه في الحضور وأعطاني حقي وزيادة جزاه الله خير. مشكلته لغته الإنجليزية تعبانة فقط. أعطيه A+++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375579-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/89", "user": "AmbitiouSS", "ts": 1401657806000, "tid": 68326, "pn": 89}}]}', 1401657806000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_20161-pe002', 'stk-_20161', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 - 142\n\nسباحة ، كرة سلة\n\n- التحضير : ببداية المحاضرة غالباً , يقبل الـMake Up ، يحضر المتأخرين لكن لو تتاخر كثير بتحصل كلام مو حلو .\n\n- طريقة الشرح : يشرح قواعد كرة السلة على السريع ، بعدين يخلينا نتدرب على حركة السلم بكل الحصص المتبقية لان الاختبار عنها\nالسباحة نفس الشيء .\n\n- الـQuizzes : اعطانا ورقة قبل الاختبار مكونة من عدة جمل ، قال ندرسها او نحفظها ، وكان الاختبار صح و خطأ من ههذه الجمل و كلهم صح الا اثنيتين خطا ، كل الكلاس اخذ فل مارك الا اثنين كان عندهم خطأ لكن اعطاهم الفل مارك .\n\n- الصوت : واضح , يتكلم غالباً بالعربي و قليل جداً بالإنقليزي .\n\n- الـGrade : A\n\n- إضافات : مدرس طييييييييييب و بقوة ، انا غبت عن اختبار السباحة و اعطاني 30 من 35 ، كل كلاسنا اخذوا A او A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438835-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/93", "user": "_20161", "ts": 1452714933000, "tid": 68326, "pn": 93}}]}', 1452714933000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_alghamdi-pe002', 'stk-abdulrahman_alghamdi', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68330", "n": "Dr. Mootaz Hasanain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**PE002 - 172 **\nالتحضير : بعد 5 دقائق من بداية الكلاس، يبدأ بالتحضير و فيه مجال انه يسمح لك بالتأخر لبعد ال5 دقائق. ويطلعك قبل النهاية ب10 دقائق.\nالشرح : يشرح المطلوب بطريقة لطيفة خفيفة بدون زيادة أو نقصان، بداية كل كلاس يراجع المعلومات السابقة.\nالكويزات : بالنسبة للاختبار النظري، أسهل ما يكون، حدد لنا الأشياء الي نحتاج نذاكرها وما خرج عنها\nالقريد النهائي : A\nالصوت : أوضح من الواضح\nإضافات : الدكتور حبيب ومتعاون جداً مع الطلاب، يعاملهم كأنهم أولاده، يهتم بفهم الطالب للجزء العملي لدرجة انه يعيد الشرح أكثر من مرة عشان الطالب يفهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498914-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mootaz-hasanain/68330/47", "user": "Abdulrahman_Alghamdi", "ts": 1536237915000, "tid": 68330, "pn": 47}}]}', 1536237915000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik123-pe002', 'stk-abdulmalik123', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68330", "n": "Dr. Mootaz Hasanain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": ".Pe002 181\nالتحضير : تحضير بالسيريال نمبر و ما يدقق على التاخير بس لا تفلها ويسمح بالميك اب بس اساله قبلها\nطريقة الشرح : الدكتور علي عبيد الي شرح مو هوا 😅\nالكويزات : واحد بس ١٠ مصطلحات من اختيارك مع تعريفهم والباقي خيارات و صح و غلط\nالصوت : جيد و واضح\nالقريد النهائي : A\nاضافات : الدكتور حبيب ومتساعد وبيعطيك الي يقدر عليه بس لا تستهبل وتحضر نفسك وتمشي لانه بيقفطك غبت عنده كثير و مشالي كم غياب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510117-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mootaz-hasanain/68330/50", "user": "abdulmalik123", "ts": 1558661808000, "tid": 68330, "pn": 50}}]}', 1558661808000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_chemical-pe002', 'stk-_chemical', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68336", "n": "Dr. H. Abu-Hilal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "وآلله آنسآن حبوب وآخلآق ويحب آلتنكيت وخآصة قبل التقييم 😆 بعد آلتقيم شي ثآني طبعآ آلكلآم pe002\n\nterm 102 بس سو آللي يقولك عليه ورآح تآخذع آلآقل a آنآ آخذت a بس سويت مقآل عن كرة آلسلة طبعآ\n\nآلمقآل على كل آلطلآب وكنت آجيب آليونيفورم دآئمآ وآسوي آللي يقوله بس ورآح تآخذ اللي يسرك آن شآء آلله\n\nوزي مآقآلو آلآخوآن آللي قبل شبك تمشي 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891491-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/h-abu-hilal/68336/61", "user": "_chemical", "ts": 1314203398000, "tid": 68336, "pn": 61}}]}', 1314203398000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-as_17-pe002', 'stk-as_17', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f68336", "n": "Dr. H. Abu-Hilal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا انا أخذت معه سلة وسباحة\nPe 002\n172\nالتحضير :\nيوميا ياخذ التحضير وبعد ٨ دقايق تقريبا يبدا يحضر\nالشرح :\nطبعا المادة ما تحتاج شرح لكن خلانا في اخر اسبوع نعمل برزينتيشن … وكل مجموعة مكونة من ثلاث أشخاص تقوم تشرح\nثم هو يجي ويسوي مراجعة سريعة للسلايدات اللي سويناها\n\nالمياجر : اختبار واحد عليه ٢٠ درجة\nويكون سهل للي مذاكر … لكن طريقة التصحيح شوي غبيه ومعقدة جدا ‍♂️\n\nإضافات :\nالدكتور حبيب جدا ينكت ويضحك معك في وقت الكلاس وغالبا يعرف اغلب طلابه باسمائهم\nانا سمعت عنه سمعة سيئة جدا … لكن حقيقة الدكتور حبيب ولكن مزحه ممكن يكون ثقيل لبعض الطلاب لذلك ما يتقبلون\nاما البونص فحقيقة … تشبكه بيعطيك بونص مب طبيعي\nانا كانت تقريبا درجاتي ٨٢ اخر شي شفت القريد حقي A+\nمع العلم اني غائب ٥ غيابات\nباختصار الدكتور في افضل منه كثير لكن هو ممتاز كذلك\n\nالقريد النهائي : A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493513-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/h-abu-hilal/68336/73", "user": "As_17", "ts": 1527915981000, "tid": 68336, "pn": 73}}]}', 1527915981000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-pe002', 'stk-rapls', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f70306", "n": "Dr. Azeem Kaukab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172 - PE002\n\nالتحضير : يحضر بالكشف بالسيريال نمبر والامور سهالات , يسمح بالميك اب وفي اخر السمستر يسال كم غياباتك , ولو قلت له انا سويت ميك اب يمسح حتى لو انت كذاب 🙂 .\n\nطريقة الشرح : شرحه اقل من المطلوب كنظري وأيضًا كعملي , ما كان مفيد .\n\nالكويزات : من ناحية الاختبار الورقي عطانا ورقة نذاكرها و جاب اختبار صعب عشر أسئلة , قال في 3 بس Tricky والصراحة كلها :))))\n\nالمياجر: ماش في السلة والسباحة , الناس اللي مستواهم ضعيف ما يعطيهم قريدات حتى لو شدوا حيلهم وتطوروا وهذا ظلم .\n\nالفاينلات : -\n\nالقريد النهائي: C\n\nالصوت: واضح وجيد\n\nإضافات : طلب منا نسوي بحث علمي , ويطلب اشياء صعبة من مواقع وكذا , الكتاب ما شرحه بس سوانا مجموعات ووزع علينا دروس وما غير يتكي لكل مجموعة ويحجر لهم , مشكلته مو معطي المادة أهمية ف إذا ما كان يعرفك او ما كنت متميز عنده وتشارك مع المنتخب ما بتاخذ قريد , أخر السمستر بيقرا اسمك ويشوف غياباتك ويطالع اول صفحة في بحثك ويعطيك قريد من راسه , وتعب السمستر كله راح , لا أنصح به .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498510-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azeem-kaukab/70306/25", "user": "Rapls", "ts": 1535726443000, "tid": 70306, "pn": 25}}]}', 1535726443000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_ali-pe002', 'stk-abo_ali', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f74184", "n": "Dr. John Allen", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "جون الن ترم 102 pe002\n\nالمدرس حبوب ما يكرف بس يعطيك حقك تمام\nالزين فيه روحه مرحه مش ميت مثل بعض المدرسن\nلكن في النهايه بتاخذ ذاك القريد اللي تستحقه\n\nاه نسيت\nبالنسبه للتحضير فيحضر كل كلاس\nوالغيابات محسوبه وما يمسحها إلا بعذر رسمي\nما اذكر اذا كان عنده ميك اب او لا , نسيت .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p996369-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-allen/74184/17", "user": "Abo_Ali", "ts": 1330498229000, "tid": 74184, "pn": 17}}]}', 1330498229000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-pe002', 'stk-chelsea_17', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f74184", "n": "Dr. John Allen", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 - Term 122\n\nالتحضير :\nبداية كل كلاس عالايباد ( وترى كل شي يسجله عالايباد )\n\nطريقة الشرح :\nعادي ما في شي مميز لكن دايم ينبه الطلاب بخصوص صحتهم الخاصه ويشطح أحيان عن الدرس , أذكر مرة جانا زعلان يوم بدت تطلع الأصوات بأمريكا للمطالبه بالماريجوانا الطبيه ( هالكلام قبل ما يتم السماح بها رسميا مثل الان )\n\nالكويزات :\nنسيت كيف كان.\n\nالمياجر:\nالفاينلات :\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور ما يطلب منك فوق جهدك أبدا ويقيمك عالجهد المبذول منك , مثلا بالسباحه الاختبار النهائي ما قدرت أسبح الى آخر المسبح تعبت فقال لي خلاص اطلع وأنا بقيمك على التكنيك أثناء السباحه ( على فكره ترى اختباره بالنهايه بالعميق لكن بعض الدكاتره لأ ) .\n\nأهم شي لا تغيب عند الدكتور وبتطلع بقريد ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373613-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-allen/74184/21", "user": "Chelsea_17", "ts": 1401322183000, "tid": 74184, "pn": 21}}]}', 1401322183000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-pe002', 'stk-user10218', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f80987", "n": "Dr. A Vargees", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 and PE 101\n\nالتحضير :\n\nكل كلاس\n\nيقبل بالميك اب في اي كلاس نفس اليوم بدون ما تعطيه خبر\n\nيمسح عنك غياب لو كلمته\nطريقة الشرح :\nزين\nسلايدات ان وجد\n\nيتكلم عن الموضوع ويعطيك أمثله\nو قصص من حياته\nالكويزات :\n\nمن الكتاب او السلايدات الي يرفعها على البلاك بورد\nو ممكن يحدد لك او يحذف\n\nوبيعطيك خبر كيف بتكون\n\nاختبرت عنده\nاختيارات + كتابة + صح و خطأ\nالمياجر:\n\nلا يوجد\nالفاينلات :\n\nاختبار رياضي\n\nالقريد النهائي:\n\nB+\n\nالصوت:\n\nواضح نوعا ما\n\nاكسنت هندي ،\n\nإضافات :\n\n* ما راح يزيدك ولا درجة تقريباٌ بيعطيك حقك\n\nانا باقي درجتين ولا زاد شي\n\n*اوقات المياجر يحاول يخفف الكلاس\n\n* حبوب ومتعاون مع الطلاب وينكت في الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437956-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-vargees/80987/21", "user": "user10218", "ts": 1451882221000, "tid": 80987, "pn": 21}}]}', 1451882221000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-pe002', 'stk-to_be_engineer', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f90478", "n": "Dr. Rakesh Tomar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(PE 002 (171\n(PE101 (172\n**التحضير:**التحضير اول خمس دقايق، تتأخر شوي يعطيك ليت بس حاول ما تخربها. عطانا فري ابسنت نهاية السمستر.\nطريقة الشرح: على سلايدات واضح جدا، بعض الاحيان يقط نكت عشان يغير الجو الممل، يحب يشوف الطلاب يسألون ويتفاعلون معه.\nالكويزات: انسى شي اسمه كتاب قبل الكويز بيعطيك هاند اوت ما يتعدى صفحة فيه الزبدة تقراه قبل الكلاس بنص ساعه تروح تجيب فل.\n**المياجر:**NA\n**الفاينلات:**NA\nالقريد النهائي: A\nالصوت: ممتاز واحسن من اقرانه من الجنسيه الهندية\nاضافات: اذا تبي تبي تنسى انا عندك PE اصلا في الجدول نزل عنده ماراح تحس في المادة ابد. سلبيته الوحيدة انه خلانا نداوم لاخر يوم لكن من حقة هالشي + الكل كان راضي عن قريده في النهاية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492644-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakesh-tomar/90478/44", "user": "To_Be_Engineer", "ts": 1526597321000, "tid": 90478, "pn": 44}}]}', 1526597321000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest333-pe002', 'stk-guest333', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f90478", "n": "Dr. Rakesh Tomar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الأستاذ تومار راكيش\n\nمحاضر\n\nPE 002\n\nبنود التقييم :\n\nالتحضير : كان يعطي 5 دقايق بعدها يحضر. يتعاون في الميك اب بشرط انك ترسله قبل الكلاس بكم ساعة.\n\nطريقة الشرح : سيء وفي العملي ما يسوي إحماء على طول يبدأ والميزة الوحيدة ان ما يطول فوق 35 دقيقة. وبقية الشرح كان بدائي جدًا.\n\nالكويزات : كويز واحد وكان سهل وينحل بالمنطق\n\nالقريد النهائي: اعطيه C مو افضل خيار وفيه الاسوء بس C كان آفرج الشعبة مع انه PE\n\nالصوت: واضح، اكسنت هندي لأنه هندي\n\nإضافات : الدكتور مستحيل يعطيك حقك كامل لازم بعسر عليك المادة والقريد مستحيل يزيدك درجة وحدة لو باقيلك درجة على القريد الي بعده. في الطائرة نقصني 5 درجات عشان الاداء في اللعبة مع العلم ان المهارات كلها سويتها بالشكل المطلوب وخاصة الارسال أي كورة تلمس الخط يعطيك صفر. تجربة ما تنعاد إن شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539543-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakesh-tomar/90478/46", "user": "guest333", "ts": 1746976237153, "tid": 90478, "pn": 46}}]}', 1746976237153, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-feras66alq-pe002', 'stk-feras66alq', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172-PE-002\nالتحضير : حريص جدا على التحضير بس الميكب مثل الحلاوة ، يعطيعك ٥ دقايق بعدها يبدا اليت والابسنت وما يخليك تدخل . ويبدا الخصم من اول غياب .\n\nمحترم جدا ويرد على الايميلات بسرعه ومتعاون واختبارات ما تهمه بقدر التحسن الي تسويه . يسأل من الي علمك عليه قبل ويعطي عليه بونص .\n\nالكويز عبارة عن ١٠ اسئلة اختيارات سهله بس كل سؤال له اكثر من اجابه لو ما حددت كل الاجابات الصحيحه بيعطيك صفر على السؤال\n\nاذا ما عجبتك درجتك النهائية تقدر تعيد الاختبار فنهاية السمستر . لو ناقصتك نص درجه على القريد الي بعده مستحيل يزيدك اياها وبيقولك تعال عد الاختبار ، يعني الرجال حقاني وبزياده والقريد الي بتحصله مثل الي تستحقه بالضبط .\n\nالتقييم النهائي : B\n\nدكتور ممتاز ومحترم جدا ويحب الضحك والوناسه بس من ناحية الدرجات وانت وفنك واجتهادك .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493052-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/5", "user": "Feras66alq", "ts": 1527379488000, "tid": 175801, "pn": 5}}]}', 1527379488000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-pe002', 'stk-user11372', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 - 182\n\nالتحضير : يعطيك 5 دقايق زيادة مثلا الكلاس يبدا 11 عندك الى 11:05 بعدين بيقولك احضر مع كلاس ثاني اشان مايعطيك Late\nوالدكتور يقبل ميك اب طول السمستر وهذا شي اسطوري منه , حتى لو تسوي ميك اب بيوم معين عادي وبالعكس متعاوووووون جدا والله\n\nطريقة الشرح : يشرح عنده سلايدات عن الكتاب , شرحه ممتاز , يطلب من الطلاب يقدمون برزنتيشن (اختياري) عليه بونص حول 4 درجات تسويه مجموعة او لحالك\n\nالكويزات : هذي المشكلة الوحيدة ممكن مع هذا الدكتور , اللي هو الاختبار النظري , شرحه روعة , اختباره النظري سهل لكن المشكلة يقولك اختر جميع الاجابات الصحيحة يعني ممكن في الخيارات تكون اكثر من اجابة صح ممكن 2 او 3 او كلهم ال 4 فلازم تظلل عليهم كلهم ولا بينقصك درجات هذي المشكلة الوحيدة فقط اللي واجهتني مع الدكتور , اله انت مذاكر صح لاتخاف بتجيهم صح لان اختباره سهل\n\nالمياجر: - مافي\n\nالفاينلات : - مافي\n\nالقريد النهائي: A+\n\nالصوت: واضح وممتاز , والاكسنت ممتاز ومفهوم .\n\nإضافات : الدكتور جدا متعاون ويعطي بونص ممكن بكل كلاس , فريق فاز على فرق = بونص , لو سوى مسابقات خارجية او محاضرات وحضرت = بونص , لو صرت مهتم معه وكذا وعرفك = بونص , شرح درس = بونص … ونهاية السمستر رفع كل الطلاب قريد مثلا واحد جايب A صار A+ وكذا متعاون مره مع القريد , لكن هذا مو معناه انت تحضر الكلاس وتنام وعندك 7 غيابات وتقول ابي A+ !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508754-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/10", "user": "user11372", "ts": 1555604420000, "tid": 175801, "pn": 10}}]}', 1555604420000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eyad_alharthi-pe002', 'stk-eyad_alharthi', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 002 / PE 101\nترم 192 (حضوري + عن بعد)\nترم 201 (عن بعد)\nالتحضير :\n- حضوري: كان عنده كشف و ينادي عالأسماء بعد بداية الكلاس بخمس دقائق.\n- عن بعد: أعطى كل واحد رقمه التسلسلي و وقت التحضير ( أيضا بعد بداية الكلاس بخمس دقائق) يبدأ كل واحد يقول رقمه بالرتيب.\nكان متسامح جدا في الميك اب ، لكن عن بعد الديبارتمنت منع الميك اب\nطريقة الشرح : رائع و يحاول يغير من روتين الحصة إما عن طريق تقسيم الشرح على الطلاب من خلال تقسيمهم لمجموعات مكونة من 4-5 طلاب. أو إنه يشرح سلايدات و يصور فيديوهات له و هو يعرض التمارين\nالكويزات : كانت عن بعد، و يحتاج لها واحد فاهم لأانها اختيارات و أكثر من خيار صح + لازم تجيب كل الخيارات الصحيحة و إلا راحت عليك درجة السؤال.\nالقريد النهائي: A\nالصوت: واضح جدا، لكن لهجته واضحة ( تشيكية) تحسها روسية\nإضافات : الدكتور المهم عنده إنه يشوفك تبذل مجهود مو مهم عنده الاتقان. فإذا شافك تحاول و تتعب يعطيك درجتك + البونص عنده عبارة عن تمارين تسويها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527532-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/14", "user": "Eyad_Alharthi", "ts": 1609698824000, "tid": 175801, "pn": 14}}]}', 1609698824000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_a7md-pe002', 'stk-king_a7md', 'PE 002', 'doc', '{"docs": [{"id": "stk-dr-f179144", "n": "Dr. Philip Watkins", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nPE 002 - 172\n\nالتحضير : يحضر بداية الكلاس بالارقام، وشديد بالحضور والتأخير\nطريقة الشرح : ممل جدا ويجيب النوم، اغلب الوقت ما افهم منه شيء\nالقريد النهائي: D\nالصوت: غير واضح بصراحة وصعب تسمعه\nإضافات : تخيل انه من بداية السمستر لين اخر كلاس ما قال عن درجات اي طالب، بالبداية بعد اول اختبار (كان بالسباحة) رحت سالته كم جبت، وقالي ما راح اقولك الا اخر السمستر\nالمشكلة اخر السمستر جيته اسال عن الدرجات يقولي ما باقولها الحين قدام الطلاب، ارسلي ايميل واقولك درجاتك، ارسلتله حوالي 5 ايميلات وما رد، يعني ما ادري وش يبي بهالاسلوب ، ما عرفت غير القريد حقي من البورتال\nوخسف فيني خسف رغم ان ما عندي اي غياب وشاركت بفريق كرة السلة وحضرت له محاضرة بالليل يقول عليها 4 درجات بونص بس للاسف القريد كان اقل من المتوقع\n\nنصيحة لا تنزل عنده اذا تبي قريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492737-pe002", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/philip-watkins/179144/2", "user": "KiNG_A7MD", "ts": 1526753236000, "tid": 179144, "pn": 2}}]}', 1526753236000, 1794835001, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
